-- IF/ELSE:
score ← 85
IF(score ≥ 90)
{
   DISPLAY "A"
}
ELSE
{
   DISPLAY "Not an A"
}

-- (score ≥ 90) = (85 ≥ 90) = false
-- IF block skipped, ELSE block executes
-- Output: Not an A

-- ------

score ← 95
IF(score ≥ 90)
{
   DISPLAY "A"
}
ELSE
{
   DISPLAY "Not an A"   -- SKIPPED
}

-- (score ≥ 90) = (95 ≥ 90) = true
-- IF block executes, ELSE block skipped
-- Output: A

-- MULTIPLE SEPARATE IF statements (ALL evaluated independently):
grade ← 85
IF(grade ≥ 90) { DISPLAY "A" }
IF(grade ≥ 80) { DISPLAY "B" }
IF(grade ≥ 70) { DISPLAY "C" }

-- Each IF is checked:
-- (85 ≥ 90) = false → no A
-- (85 ≥ 80) = true  → displays B
-- (85 ≥ 70) = true  → displays C
-- Output: B C  ← TWO outputs!

-- ------

-- IF/ELSE chain (only ONE block executes):
grade ← 85
IF(grade ≥ 90)
{
   DISPLAY "A"
}
ELSE
{
   IF(grade ≥ 80)
   {
      DISPLAY "B"
   }
   ELSE
   {
      DISPLAY "C or below"
   }
}

-- (85 ≥ 90) = false → go to ELSE
-- (85 ≥ 80) = true  → display B, inner ELSE skipped
-- Output: B  ← ONE output only

x ← 5

IF(x > 3)            -- (5 > 3) = true → executes
{
   DISPLAY "A"
}

IF(x > 4)            -- (5 > 4) = true → executes
{
   DISPLAY "B"
}
ELSE
{
   DISPLAY "C"        -- SKIPPED because IF was true
}

IF(x > 10)           -- (5 > 10) = false → skipped
{
   DISPLAY "D"        -- SKIPPED
}

-- Output: A B
-- The first IF has no ELSE, so skipping it means no output from it
-- The second IF/ELSE: B executes, C skipped
-- The third IF: false, no ELSE, no output
